def trib(n, memo=None):
    if memo is None:
        memo = {}
    if n < 2:
        return 0
    if n == 2:
        return 1
    if n in memo:
        return memo[n]
    memo[n] = trib(n - 1, memo) + trib(n - 2, memo) + trib(n - 3, memo)
    return memo[n]

