def min_monedas(monedas, V):
    INF = float('inf')
    dp = [0] + [INF] * V
    for v in range(1, V + 1):
        for c in monedas:
            if c <= v and dp[v - c] + 1 < dp[v]:
                dp[v] = dp[v - c] + 1
    return dp[V] if dp[V] != INF else -1

